class Solution:
    def heightOfTree(self, root) -> int:
        if not root:
            return 0
        # leaf node: both children are None or point to non-child
        if not root.left and not root.right:
            return 0
        left_h = self.heightOfTree(root.left) if root.left and root.left.parent == root else -1
        right_h = self.heightOfTree(root.right) if root.right and root.right.parent == root else -1
        # Simpler approach: leaf has children that are actually next pointers
        res = 0
        if root.left:
            res = max(res, 1 + self.heightOfTree(root.left))
        if root.right:
            res = max(res, 1 + self.heightOfTree(root.right))
        return res

