import asyncio
def promisify(fn):
    async def wrapper(*args):
        loop = asyncio.get_event_loop()
        future = loop.create_future()
        def callback(err, result):
            if err:
                future.set_exception(Exception(err))
            else:
                future.set_result(result)
        fn(*args, callback)
        return await future
    return wrapper

