class Solution:
    def minimumString(self, a, b, c):
        from itertools import permutations
        def merge(s1, s2):
            if s2 in s1:
                return s1
            for i in range(min(len(s1), len(s2)), 0, -1):
                if s1.endswith(s2[:i]):
                    return s1 + s2[i:]
            return s1 + s2
        ans = None
        for p in permutations([a, b, c]):
