        return ans

class Solution:
    def countSteppingNumbers(self, low, high):
        MOD = 10**9 + 7
        def count(num_str):
            from functools import lru_cache
            n = len(num_str)
            @lru_cache(maxsize=None)
            def dp(pos, prev, tight, started):
                if pos == n:
                    return 1 if started else 0
                limit = int(num_str[pos]) if tight else 9
                res = 0
                for d in range(0, limit + 1):
                    if not started and d == 0:
                        res += dp(pos+1, -1, False, False)
                    elif not started:
                        res += dp(pos+1, d, tight and d == limit, True)
                    elif abs(d - prev) == 1:
                        res += dp(pos+1, d, tight and d == limit, True)
                return res % MOD
            return dp(0, -1, True, False)
        def subtract_one(s):
            s = list(s)
            i = len(s) - 1
            while i >= 0 and s[i] == '0':
                s[i] = '9'
                i -= 1
            s[i] = str(int(s[i]) - 1)
            return ''.join(s).lstrip('0') or '0'
        return (count(high) - count(subtract_one(low))) % MOD

