    def minimumTime(self, grid):
        from collections import deque
        m, n = len(grid), len(grid[0])
        flood_time = [[float('inf')] * n for _ in range(m)]
        q = deque()
        start = end = None
        for i in range(m):
            for j in range(n):
                if grid[i][j] == '*':
                    flood_time[i][j] = 0
                    q.append((i, j))
                elif grid[i][j] == 'S':
                    start = (i, j)
                elif grid[i][j] == 'D':
                    end = (i, j)
        while q:
            x, y = q.popleft()
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0<=nx<m and 0<=ny<n and flood_time[nx][ny]==float('inf') and grid[nx][ny]!='X' and grid[nx][ny]!='D':
                    flood_time[nx][ny] = flood_time[x][y] + 1
                    q.append((nx, ny))
        dist = [[float('inf')]*n for _ in range(m)]
        dist[start[0]][start[1]] = 0
        q = deque([start])
        while q:
            x, y = q.popleft()
            if (x, y) == end:
                return dist[x][y]
            for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
                nx, ny = x+dx, y+dy
                if 0<=nx<m and 0<=ny<n and dist[nx][ny]==float('inf') and grid[nx][ny]!='X':
                    if dist[x][y]+1 < flood_time[nx][ny] or (nx,ny)==end:
                        dist[nx][ny] = dist[x][y]+1
                        q.append((nx, ny))
        return -1

