class Solution:
    def maximumScore(self, nums, k):
        MOD = 10**9 + 7
        n = len(nums)
        def prime_score(x):
            count = 0
            d = 2
            while d * d <= x:
                if x % d == 0:
                    count += 1
                    while x % d == 0:
                        x //= d
                d += 1
            if x > 1:
                count += 1
            return count
        scores = [prime_score(x) for x in nums]
        left = [-1] * n
        right = [n] * n
        stack = []
        for i in range(n):
            while stack and scores[stack[-1]] < scores[i]:
                right[stack.pop()] = i
            left[i] = stack[-1] if stack else -1
            stack.append(i)
        pairs = sorted(range(n), key=lambda i: -nums[i])
        ans = 1
        for i in pairs:
            cnt = (i - left[i]) * (right[i] - i)
            use = min(cnt, k)
            ans = ans * pow(nums[i], use, MOD) % MOD
            k -= use
            if k == 0:
                break
        return ans

