        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i+1] = prefix[i] + prices[i]
        ans = []
        for budget, k in queries:
            lo, hi = 0, k
            while lo < hi:
                mid = (lo + hi) // 2
                # mid items from front, k-mid from back
                if prices[mid] <= 2 * budget - prices[n - (k - mid)]:
                    lo = mid + 1
                else:
                    hi = mid
            front = lo
            back = k - front
            loss = prefix[front] + (2 * budget * back - (prefix[n] - prefix[n - back]))
            ans.append(loss)
        return ans
